package pythonparity

import (
	"encoding/json"
	"math"
	"os"
	"strconv"
	"testing"
)

// The golden lives under tests/fixtures (shared with the Python-side
// generator) rather than under this package's own testdata, because it is
// generated by importing dev_health_ops.work_graph.investment.membership's
// _float_value directly -- see
// tests/fixtures/generate_python_float_golden.py. Only string_cases are
// relevant here: typed_cases pin _float_value's bespoke non-string coercion
// (bool/int/list/dict all folding to 0.0 on the Go side of THAT port), not
// CPython float(str)'s own grammar, which is what ParseFloat mirrors.
type parseFloatGolden struct {
	StringCases []struct {
		InputCodepoints       []int  `json:"input_codepoints"`
		FloatRaisesValueError bool   `json:"float_raises_value_error"`
		ResultBits            string `json:"result_bits"`
		ResultRepr            string `json:"result_repr"`
	} `json:"string_cases"`
}

func loadParseFloatGolden(t *testing.T) parseFloatGolden {
	t.Helper()
	raw, err := os.ReadFile("../../tests/fixtures/python_float_python_golden.json")
	if err != nil {
		t.Fatalf("read golden: %v", err)
	}
	var golden parseFloatGolden
	if err := json.Unmarshal(raw, &golden); err != nil {
		t.Fatalf("decode golden: %v", err)
	}
	if len(golden.StringCases) == 0 {
		t.Fatalf("golden has no string_cases")
	}
	return golden
}

// TestParseFloatMatchesGoldenCorpus bit-compares ParseFloat against every
// string_cases entry CPython's own float(str) produced.
//
// Bits, not values: -0.0 == 0.0 is true in both languages, and NaN != NaN in
// both, so a value comparison is blind to a sign-of-zero or NaN-payload
// divergence -- exactly the hole a value-based comparator left open
// elsewhere in this package's history (noted in the corpus generator).
func TestParseFloatMatchesGoldenCorpus(t *testing.T) {
	golden := loadParseFloatGolden(t)
	for _, tc := range golden.StringCases {
		input := string(codepointsToRunes(tc.InputCodepoints))
		t.Run(tc.ResultRepr+"/"+input, func(t *testing.T) {
			value, ok := ParseFloat(input)
			if tc.FloatRaisesValueError {
				if ok {
					t.Fatalf("ParseFloat(%q) = %v, ok=true; CPython float() raises ValueError", input, value)
				}
				return
			}
			if !ok {
				t.Fatalf("ParseFloat(%q) ok=false; CPython float() = %s", input, tc.ResultRepr)
			}
			gotBits := math.Float64bits(value)
			wantBits := parseHexBits(t, tc.ResultBits)
			if gotBits != wantBits {
				t.Fatalf("ParseFloat(%q) bits = %016x, want %016x (CPython repr %s)", input, gotBits, wantBits, tc.ResultRepr)
			}
		})
	}
}

func codepointsToRunes(codepoints []int) []rune {
	runes := make([]rune, len(codepoints))
	for i, c := range codepoints {
		runes[i] = rune(c)
	}
	return runes
}

func parseHexBits(t *testing.T, hex string) uint64 {
	t.Helper()
	bits, err := strconv.ParseUint(hex, 16, 64)
	if err != nil {
		t.Fatalf("parse result_bits %q: %v", hex, err)
	}
	return bits
}
